1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	
60	const alikeItemGroups = (items: Item[]): Item[][] => [
61	  ...items
62	    .reduce(
63	      (groupsByType, item) =>
64	        groupsByType.set(item.type, [
65	          ...(groupsByType.get(item.type) ?? []),
66	          item,
67	        ]),
68	      new Map<string, Item[]>(),
69	    )
70	    .values(),
71	];
72	
73	const basePremiumOfGroup = (group: Item[]): number =>
74	  group.length === BLOCK_SIZE
75	    ? BLOCK_BASE_PREMIUM
76	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
77	
78	const totalBasePremiumOf = (items: Item[]): number =>
79	  alikeItemGroups(items).reduce(
80	    (total, group) => total + basePremiumOfGroup(group),
81	    0,
82	  );
83	
84	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
85	
86	type Rule<Subject> = {
87	  appliesTo: (subject: Subject) => boolean;
88	  rate: number;
89	};
90	
91	const totalRateOf = <Subject,>(
92	  rules: Rule<Subject>[],
93	  subject: Subject,
94	): number =>
95	  rules.reduce(
96	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
97	    0,
98	  );
99	
100	const CURSE_SURCHARGE_RATE = 0.5;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	
104	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
105	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
106	  {
107	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
108	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
109	  },
110	];
111	
112	const itemSurchargeOf = (item: Item): number =>
113	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
114	
115	const totalItemSurchargeOf = (items: Item[]): number =>
116	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
117	
118	const LOYALTY_YEARS_THRESHOLD = 2;
119	const LOYALTY_DISCOUNT_RATE = -0.2;
120	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
121	
122	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
123	
124	type PolicyContext = {
125	  customer: Customer;
126	  previousContracts: number;
127	};
128	
129	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
130	  {
131	    appliesTo: ({ customer }) =>
132	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
133	    rate: LOYALTY_DISCOUNT_RATE,
134	  },
135	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
136	  {
137	    appliesTo: ({ previousContracts }) => previousContracts > 0,
138	    rate: FOLLOW_UP_DISCOUNT_RATE,
139	  },
140	];
141	
142	const quotePremium = (items: Item[], policy: PolicyContext): number => {
143	  const basePremium = totalBasePremiumOf(items);
144	
145	  return roundedUpInMHPCOsFavour(
146	    basePremium +
147	      totalItemSurchargeOf(items) +
148	      basePremium * totalRateOf(POLICY_MODIFIER_RULES, policy) +
149	      PROCESSING_FEE,
150	  );
151	};
152	
153	const INSURANCE_VALUES: Record<string, number> = {
154	  sword: 1000,
155	  amulet: 600,
156	  staff: 800,
157	  potion: 400,
158	  rune: 250,
159	  moonstone: 250,
160	};
161	
162	const DEDUCTIBLE = 100;
163	const CAP_MULTIPLIER = 2;
164	
165	const insuranceSumOf = (items: Item[]): number =>
166	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
167	
168	const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;
169	
170	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
171	
172	type ClaimResult = {
173	  payout: number;
174	  remainingCap: number;
175	};
176	
177	const totalPayoutFor = (damages: Damage[]): number =>
178	  damages.reduce((total, damage) => total + payoutForDamage(damage), 0);
179	
180	const settleClaim = (incident: Incident, policy: QuoteStep): ClaimResult => {
181	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
182	  const payout = totalPayoutFor(incident.damages);
183	
184	  return { payout, remainingCap: cap - payout };
185	};
186	
187	export const runScenario = (scenario: Scenario): ScenarioResult => {
188	  const quotesBefore = (index: number): number =>
189	    scenario.steps.slice(0, index).filter(isQuote).length;
190	
191	  return {
192	    results: scenario.steps.map((step, index) =>
193	      isQuote(step)
194	        ? {
195	            premium: quotePremium(step.items, {
196	              customer: scenario.customer,
197	              previousContracts: quotesBefore(index),
198	            }),
199	          }
200	        : settleClaim(step.incident, scenario.steps[step.policy] as QuoteStep),
201	    ),
202	  };
203	};
